package com.example.reconciliation.batch;

import org.springframework.batch.core.JobExecution;
import org.springframework.batch.core.JobInstance;
import org.springframework.batch.core.StepExecution;
import org.springframework.batch.core.explore.JobExplorer;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.util.List;

@Configuration
public class JobRepositoryInspectionConfig {

    // JobExplorer provides read-only access to the JobRepository tables.
    // Use it for dashboards, operational queries, and debugging.

    @Bean
    public JobRepositoryInspector jobRepositoryInspector(JobExplorer jobExplorer) {
        return new JobRepositoryInspector(jobExplorer);
    }

    public static class JobRepositoryInspector {
        private final JobExplorer jobExplorer;

        public JobRepositoryInspector(JobExplorer jobExplorer) {
            this.jobExplorer = jobExplorer;
        }

        public void inspectJobHistory(String jobName) {
            // BATCH_JOB_INSTANCE: find all instances of this job name
            List<JobInstance> instances = jobExplorer.findJobInstancesByJobName(jobName, 0, 10);

            for (JobInstance instance : instances) {
                System.out.printf("Instance ID: %d, Parameters: %s%n",
                        instance.getId(), instance.getJobParameters());

                // BATCH_JOB_EXECUTION: all attempts for this instance
                List<JobExecution> executions = jobExplorer.getJobExecutions(instance);
                for (JobExecution execution : executions) {
                    System.out.printf("  Execution ID: %d, Status: %s, Exit: %s, Start: %s, End: %s%n",
                            execution.getId(),
                            execution.getStatus(),
                            execution.getExitStatus(),
                            execution.getStartTime(),
                            execution.getEndTime());

                    // BATCH_STEP_EXECUTION: all steps in this execution
                    for (StepExecution stepExecution : execution.getStepExecutions()) {
                        System.out.printf("    Step: %s, Read: %d, Write: %d, Commit: %d, Skip: %d, Status: %s%n",
                                stepExecution.getStepName(),
                                stepExecution.getReadCount(),
                                stepExecution.getWriteCount(),
                                stepExecution.getCommitCount(),
                                stepExecution.getSkipCount(),
                                stepExecution.getStatus());

                        // STEP_EXECUTION_CONTEXT: restart state
                        if (stepExecution.getExecutionContext().containsKey("FlatFileItemReader.read.count")) {
                            System.out.printf("      Restart position (line): %d%n",
                                    stepExecution.getExecutionContext().getLong("FlatFileItemReader.read.count"));
                        }
                    }
                }
            }
        }
    }
}

package com.example.reconciliation.config;

import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.repository.support.JobRepositoryFactoryBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Primary;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.datasource.init.DataSourceInitializer;
import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.annotation.Isolation;

import javax.sql.DataSource;

@Configuration
public class JobRepositorySetupConfig {

    // Custom JobRepository with dedicated DataSource and table prefix
    @Bean
    public JobRepository jobRepository(
            DataSource batchMetadataDataSource,
            PlatformTransactionManager batchTransactionManager) throws Exception {

        JobRepositoryFactoryBean factory = new JobRepositoryFactoryBean();
        factory.setDataSource(batchMetadataDataSource);
        factory.setTransactionManager(batchTransactionManager);
        factory.setTablePrefix("RECON_");
        // SERIALIZABLE prevents duplicate JobExecution under concurrent launches.
        // Override only if your database has serialization performance issues
        // and you have alternative deduplication (e.g., application-level locking).
        factory.setIsolationLevelForCreate(Isolation.SERIALIZABLE.value());
        factory.setMaxVarCharLength(2500);
        factory.afterPropertiesSet();
        return factory.getObject();
    }

    // Production: schema managed by Flyway/Liquibase, not Spring Boot auto-init.
    // This bean is only active in dev/test profiles.
    @Bean
    public DataSourceInitializer batchSchemaInitializer(DataSource batchMetadataDataSource) {
        DataSourceInitializer initializer = new DataSourceInitializer();
        initializer.setDataSource(batchMetadataDataSource);

        ResourceDatabasePopulator populator = new ResourceDatabasePopulator();
        // Custom DDL with RECON_ prefix matching the JobRepository configuration.
        // In production, this is handled by Flyway migration V001__create_batch_schema.sql
        populator.addScript(new ClassPathResource("schema-recon-batch.sql"));
        initializer.setDatabasePopulator(populator);

        return initializer;
    }

    // application.properties / application.yml:
    //
    // spring.batch.jdbc.initialize-schema=never  # Production: DBA/Flyway owns schema
    // spring.batch.jdbc.initialize-schema=embedded  # Default: only for H2/Derby
    // spring.batch.jdbc.initialize-schema=always  # Dev: recreate every startup
}

package com.example.reconciliation.config;

import org.springframework.batch.core.configuration.annotation.EnableBatchProcessing;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.repository.support.JobRepositoryFactoryBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.transaction.PlatformTransactionManager;

import javax.sql.DataSource;

@Configuration
// WRONG for Spring Boot 3.5 unless you explicitly need custom infrastructure:
// @EnableBatchProcessing  // <-- This disables Boot's auto-config!
//
// CORRECT approach: let Boot auto-configure, and only override specific beans.
public class CorrectBatchConfig {

    // Spring Boot 3.5 auto-configures JobRepository, JobLauncher, JobExplorer
    // from the primary DataSource and PlatformTransactionManager automatically.
    // No annotation needed.

    // If you need a custom JobRepository (e.g., dedicated DataSource for metadata):
    @Bean
    public JobRepository customJobRepository(
            DataSource batchMetadataDataSource,
            PlatformTransactionManager batchTransactionManager) throws Exception {

        JobRepositoryFactoryBean factory = new JobRepositoryFactoryBean();
        factory.setDataSource(batchMetadataDataSource);
        factory.setTransactionManager(batchTransactionManager);
        factory.afterPropertiesSet();
        return factory.getObject();
    }

    // If you need a custom transaction manager for batch (e.g., JTA):
    // @Bean
    // public PlatformTransactionManager batchTransactionManager() {
    //     return new JtaTransactionManager(); // or DataSourceTransactionManager for dedicated DS
    // }

    // Boot auto-configuration will inject the custom JobRepository into
    // JobBuilder and StepBuilder constructors throughout your @Configuration classes.
}

