package com.example.reconciliation.batch;

import com.example.reconciliation.domain.ReconciledTransaction;
import com.example.reconciliation.domain.TransactionRecord;
import org.springframework.batch.core.Job;
import org.springframework.batch.core.Step;
import org.springframework.batch.core.job.builder.JobBuilder;
import org.springframework.batch.core.repository.JobRepository;
import org.springframework.batch.core.step.builder.StepBuilder;
import org.springframework.batch.item.ItemProcessor;
import org.springframework.batch.item.ItemReader;
import org.springframework.batch.item.ItemWriter;
import org.springframework.batch.item.file.FlatFileItemReader;
import org.springframework.batch.item.file.builder.FlatFileItemReaderBuilder;
import org.springframework.batch.item.file.mapping.RecordFieldSetMapper;
import org.springframework.batch.repeat.RepeatStatus;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.io.FileSystemResource;
import org.springframework.core.task.TaskExecutor;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;
import org.springframework.transaction.PlatformTransactionManager;

import java.math.BigDecimal;

@Configuration
public class FluentApiConfig {

    private final JobRepository jobRepository;
    private final PlatformTransactionManager transactionManager;

    // Constructor injection — Spring Boot 3.5 auto-configures these beans.
    public FluentApiConfig(JobRepository jobRepository,
                           PlatformTransactionManager transactionManager) {
        this.jobRepository = jobRepository;
        this.transactionManager = transactionManager;
    }

    @Bean
    public Job fluentApiJob() {
        // JobBuilder constructor: name + JobRepository
        return new JobBuilder("fluentApiJob", jobRepository)
                .start(chunkStep())
                .next(taskletStep())
                .build();
    }

    @Bean
    public Step chunkStep() {
        // StepBuilder constructor: name + JobRepository
        // Then declare chunk type and size, plus transaction manager.
        return new StepBuilder("chunkStep", jobRepository)
                .<TransactionRecord, ReconciledTransaction>chunk(100, transactionManager)
                .reader(csvReader())
                .processor(reconciliationProcessor())
                .writer(reconciliationWriter())
                // Additional configuration via fluent chaining:
                .faultTolerant()
                .skipLimit(5)
                .skip(IllegalArgumentException.class)
                .retryLimit(3)
                .retry(org.springframework.dao.TransientDataAccessException.class)
                .taskExecutor(stepTaskExecutor())
                .build();
    }

    @Bean
    public Step taskletStep() {
        // Tasklet step: no chunk, just a single-shot operation
        return new StepBuilder("taskletStep", jobRepository)
                .tasklet((contribution, chunkContext) -> {
                    System.out.println("Tasklet executed: post-processing cleanup");
                    return RepeatStatus.FINISHED;
                }, transactionManager)
                .build();
    }

    @Bean
    public FlatFileItemReader<TransactionRecord> csvReader() {
        return new FlatFileItemReaderBuilder<TransactionRecord>()
                .name("csvReader")
                .resource(new FileSystemResource("data/transactions.csv"))
                .linesToSkip(1)
                .delimited()
                .names("transactionId", "accountId", "amount", "currency", "transactionDate", "status")
                .fieldSetMapper(new RecordFieldSetMapper<>(TransactionRecord.class))
                .build();
    }

    @Bean
    public ItemProcessor<TransactionRecord, ReconciledTransaction> reconciliationProcessor() {
        return record -> {
            boolean matched = record.amount() != null
                    && record.amount().compareTo(BigDecimal.ZERO) > 0
                    && "SETTLED".equals(record.status());
            return new ReconciledTransaction(
                    record.transactionId(),
                    record.accountId(),
                    record.amount(),
                    matched ? "MATCHED" : "MISMATCHED",
                    "Fluent API demo"
            );
        };
    }

    @Bean
    public ItemWriter<ReconciledTransaction> reconciliationWriter() {
        return chunk -> chunk.forEach(tx ->
            System.out.printf("[Fluent] %s -> %s%n", tx.transactionId(), tx.reconciliationStatus())
        );
    }

    @Bean
    public TaskExecutor stepTaskExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(4);
        executor.setThreadNamePrefix("fluent-step-");
        executor.initialize();
        return executor;
    }
}

package com.example.reconciliation.config;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.datasource.embedded.EmbeddedDatabaseBuilder;
import org.springframework.jdbc.datasource.embedded.EmbeddedDatabaseType;

import javax.sql.DataSource;

@TestConfiguration
public class TestDataSourceConfig {

    // Test-specific H2 database for integration tests.
    // Spring Boot auto-configures JdbcJobRepository against this DataSource.
    // The schema is created automatically because
    // spring.batch.jdbc.initialize-schema=embedded (default for embedded DBs).
    @Bean
    @Primary
    public DataSource testDataSource() {
        return new EmbeddedDatabaseBuilder()
                .setType(EmbeddedDatabaseType.H2)
                .setName("batch_test_db")
                .build();
    }

    // application-test.yml:
    //
    // spring:
    //   datasource:
    //     url: jdbc:h2:mem:batch_test_db
    //     driver-class-name: org.h2.Driver
    //   batch:
    //     jdbc:
    //       initialize-schema: embedded  # default, creates BATCH_* tables automatically
    //
    // This ensures tests use the EXACT same JdbcJobRepository implementation
    // as production, just against an in-memory H2 database instead of PostgreSQL.
}

